--- @class TangSeng
--- 唐僧框架的门面，在框架正常启动后，才可以使用

local module = {}
local FacadeFactory = require(script.FacadeFactory)
local InjectionWrap = require(script.InjectionWrap)
local ActivatorUtilities = require(script.Core.DependencyInjection.ActivatorUtilities)


module.GetServices = function()
	return FacadeFactory.GetServices()
end


module.GetPlayerScope = function(userIdOrPlayer:number|Player)
	return FacadeFactory.GetPlayerScope(userIdOrPlayer)
end


--- @function GetFacade
--- @within TangSeng
--- 获取根门面
module.GetFacade = function(): TangSengFacade
	return FacadeFactory.GetRootFacade()
end

--- @function GetFacadeOfPlayer
--- @within TangSeng
--- 获取玩家门面, 如果玩家未准备好, 则返回 nil
module.GetFacadeOfPlayer = function(playerOrUserId: Player | number): TangSengFacade
	return FacadeFactory.GetFacadeOfPlayer(playerOrUserId)
end

--[=[

	@function InjectionWrap
	@within TangSeng
	本方法会为 handler 额外添加一个参数 TangSengFacade

	@param handler  需要被包装的函数
	@param argsCount  参数数量
	@param isPlayerScope  是否是玩家域调用

	:::note 
	
	`isPlayerScope` 参数特别说明
	* true: 将注入玩家门面,如果是，则handler接收的第一个参数必须是 Player 类型
	* false: 将注入根门面
	:::

]=]
function module.InjectionWrap(handler: (...any) -> (), argsCount: number, isPlayerScope: boolean?)
	return InjectionWrap(handler, argsCount, isPlayerScope)
end

--- @function GetActivatorUtilities
--- @within TangSeng
--- 获取实例工具
module.GetActivatorUtilities = function(): IActivatorUtilities
	return ActivatorUtilities
end

return module
